import { Component, computed, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero } from '../../domain/hero.model';
import { PowerMeter } from '../power-meter/power-meter';
import { StatusBadge } from '../status-badge/status-badge';

@Component({
  selector: 'app-hero-card',
  imports: [RouterLink, HlmAvatarImports, HlmBadgeImports, HlmCardImports, PowerMeter, StatusBadge],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();

  /** Up to two letters from the hero's name, for the avatar fallback. */
  protected readonly initials = computed(() =>
    this.hero()
      .name.split(/\s+/)
      .filter((word) => /^[A-Za-z]/.test(word))
      .slice(0, 2)
      .map((word) => word.charAt(0).toUpperCase())
      .join(''),
  );
}
import { Component, input } from '@angular/core';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideActivity, lucideShieldAlert, lucideUserCheck, lucideZap } from '@ng-icons/lucide';
import { HlmCardImports } from '@spartan-ng/helm/card';

/** The icons a stat tile can show. Each is registered on the tile below. */
export type StatTileIcon = 'lucideUserCheck' | 'lucideActivity' | 'lucideZap' | 'lucideShieldAlert';

@Component({
  selector: 'app-stat-tile',
  imports: [NgIcon, HlmCardImports],
  providers: [provideIcons({ lucideUserCheck, lucideActivity, lucideZap, lucideShieldAlert })],
  templateUrl: './stat-tile.html',
  styleUrl: './stat-tile.css',
})
export class StatTile {
  readonly label = input.required<string>();
  readonly value = input.required<string | number>();
  readonly hint = input('');
  readonly icon = input.required<StatTileIcon>();
}
<div hlmCard class="stat-tile">
  <div hlmCardHeader class="stat-tile__header">
    <p hlmCardDescription>{{ label() }}</p>
    <ng-icon class="stat-tile__icon" aria-hidden="true" [name]="icon()" />
  </div>
  <div hlmCardContent>
    <p hlmCardTitle emphasis="stat">{{ value() }}</p>
    <p hlmCardDescription>{{ hint() }}</p>
  </div>
</div>
import { Component, input } from '@angular/core';

/** A horizontal bar for a 0 to 100 power index. Presentational: it only draws the value it is given. */
@Component({
  selector: 'app-power-meter',
  templateUrl: './power-meter.html',
  styleUrl: './power-meter.css',
})
export class PowerMeter {
  readonly value = input.required<number>();
  readonly label = input.required<string>();
}
import { Component, computed, input } from '@angular/core';
import { type BadgeVariants, HlmBadgeImports } from '@spartan-ng/helm/badge';
import type { HeroStatus } from '../../domain/hero.model';

type BadgeVariant = NonNullable<BadgeVariants['variant']>;

/** Each status carries its own colour; Reserve stays neutral because it is not a warning. */
const STATUS_VARIANT: Record<HeroStatus, BadgeVariant> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

/** A hero's status as a badge. Presentational: the status arrives as an input. */
@Component({
  selector: 'app-status-badge',
  imports: [HlmBadgeImports],
  templateUrl: './status-badge.html',
  styleUrl: './status-badge.css',
})
export class StatusBadge {
  readonly status = input.required<HeroStatus>();

  protected readonly variant = computed(() => STATUS_VARIANT[this.status()]);
}

