// Throwaway verification, kept outside the repo. Reuses the harness helpers by absolute import.
const ROOT = 'file:///D:/Repos/angular-jig';
const { assertResponsive } = await import(`${ROOT}/harness/gate/check-responsive.mjs`);
const { serveStatic, launchChromium } = await import(`${ROOT}/harness/playwright/serve-and-visit.mjs`);
const { join } = await import('node:path');

const DIST = 'D:/Repos/angular-jig/dist/angular-jig/browser';
const screens = [
  ['dashboard', 'app-dashboard'],
  ['roster', 'app-heroes'],
  ['detail/HRO-0007', 'app-hero-detail'],
  ['missions', 'app-missions'],
  ['threats', 'app-threats'],
  ['recruit', 'app-recruit'],
  ['settings', 'app-settings'],
];

const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
const results = { responsive: {}, flow: [] };
try {
  for (const [route, anchor] of screens) {
    const { failures } = await assertResponsive({ origin: srv.origin, route, anchorSelector: anchor, browser });
    results.responsive[route] = failures.length === 0 ? 'pass' : failures.slice(0, 6);
  }

  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  const nav = () => page.getByRole('navigation', { name: 'Primary' });
  const step = async (name, fn) => {
    try {
      await fn();
      results.flow.push(`ok   ${name}`);
    } catch (e) {
      results.flow.push(`FAIL ${name}: ${String(e).split('\n')[0]}`);
    }
  };

  await page.goto(`${srv.origin}/detail/HRO-0007`);
  await step('detail: edit name and save', async () => {
    await page.getByRole('tab', { name: 'Edit', exact: true }).click();
    await page.locator('#hero-name').fill('Silverwing Prime');
    await page.getByRole('button', { name: 'Save changes' }).click();
    await page.getByText('Changes saved.').waitFor({ timeout: 3000 });
  });
  await step('dashboard reflects the saved name', async () => {
    await nav().getByRole('link', { name: 'Dashboard', exact: true }).click();
    await page.getByRole('table').getByText('Silverwing Prime').waitFor({ timeout: 3000 });
  });
  await step('roster reflects the saved name', async () => {
    await nav().getByRole('link', { name: 'Roster', exact: true }).click();
    await page.getByRole('link', { name: 'Silverwing Prime', exact: true }).first().waitFor({ timeout: 3000 });
  });
  await step('recruit creates a hero and opens its detail', async () => {
    await nav().getByRole('link', { name: 'Recruit', exact: true }).click();
    await page.locator('#recruit-name').fill('Test Recruit');
    await page.locator('#recruit-alias').fill('Probe');
    await page.getByRole('button', { name: 'Recruit hero' }).click();
    await page.waitForURL(/\/detail\/HRO-0013$/, { timeout: 3000 });
    await page.getByRole('heading', { name: 'Test Recruit', level: 1 }).waitFor({ timeout: 3000 });
  });
  await step('retire removes the hero and returns to roster', async () => {
    await page.getByRole('button', { name: 'Retire', exact: true }).click();
    await page.getByRole('button', { name: 'Retire hero' }).click();
    await page.waitForURL(/\/roster$/, { timeout: 3000 });
    await page.getByText('12 of 12 heroes').waitFor({ timeout: 3000 });
  });
  await step('threats lists the MIA hero', async () => {
    await nav().getByRole('link', { name: 'Threats', exact: true }).click();
    await page.getByText('Null').first().waitFor({ timeout: 3000 });
  });
  await step('settings: dark theme sets .dark on html', async () => {
    await nav().getByRole('link', { name: 'Settings', exact: true }).click();
    await page.getByRole('button', { name: 'Dark', exact: true }).click();
    await page.waitForFunction(() => document.documentElement.classList.contains('dark'), null, { timeout: 3000 });
  });
  results.pageErrors = errors;
  await page.close();
} finally {
  await browser.close();
  await srv.close();
}
process.stdout.write(JSON.stringify(results, null, 2) + '\n');
